/* ---------- 지역 인덱스 ---------- */
const SIDO_BY = {}, SG_BY = {}, DONG_BY = {}, SIDO_SGS = [], SG_DONGS = [];
REG.SIDO.forEach((s, i) => { SIDO_BY[s[0]] = i; SIDO_SGS[i] = []; });
REG.SG.forEach((g, i) => { SG_BY[REG.SIDO[g[0]][0] + '/' + g[1]] = i; SIDO_SGS[g[0]].push(i); SG_DONGS[i] = []; });
REG.DONG.forEach((d, i) => { const g = REG.SG[d[0]]; DONG_BY[REG.SIDO[g[0]][0] + '/' + g[1] + '/' + d[1]] = i; SG_DONGS[d[0]].push(i); });

function regionLabel(sd, sg, dg) {
  const si = SIDO_BY[sd]; if (si === undefined) return '';
  let t = REG.SIDO[si][1];
  if (sg) { const gi = SG_BY[sd + '/' + sg]; if (gi === undefined) return t; t += ' ' + REG.SG[gi][2]; }
  if (sg && dg) { const di = DONG_BY[sd + '/' + sg + '/' + dg]; if (di !== undefined) t += ' ' + REG.DONG[di][2]; }
  return t;
}

/* ---------- 해시 시드 선택 (FNV-1a) ---------- */
function fnv(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
}
function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }
/* 시드마다 시작 인덱스와 보폭을 달리해 n개를 겹치지 않게 고른다 */
function pickN(arr, seed, n) {
  const len = arr.length; if (!len) return [];
  n = Math.min(n, len);
  const h = fnv(SITE.key + '|' + seed);
  const start = h % len;
  let step = 1 + ((h >>> 11) % Math.max(1, len - 1));
  while (gcd(step, len) !== 1) step = step % len + 1;
  const out = [];
  for (let i = 0; i < n; i++) out.push(arr[(start + i * step) % len]);
  return out;
}
function pick1(arr, seed) { return pickN(arr, seed, 1)[0]; }

/* 다른 제품 하나만 다루는 문단은 해당 제품 페이지에서 뺀다 (예: 키오스크 페이지에 테이블오더 전용 문단) */
const _fp = new Map();
function forProd(arr, prodKey) {
  if (!prodKey || !Array.isArray(arr)) return arr;
  let m = _fp.get(arr); if (!m) { m = {}; _fp.set(arr, m); }
  if (m[prodKey]) return m[prodKey];
  const cur = PRODUCT_MAP[prodKey].ko;
  const others = PRODUCTS.filter(p => p.key !== prodKey).map(p => p.ko);
  const f = arr.filter(x => {
    const s = typeof x === 'string' ? x : [x.t, x.d, x.q, x.a].filter(Boolean).join(' ');
    if (s.includes('{제품}') || s.includes(cur)) return true;
    return others.filter(o => s.includes(o)).length !== 1;
  });
  return (m[prodKey] = f.length >= Math.min(6, arr.length) ? f : arr);
}


/* ---------- 텍스트 치환 ---------- */
const SYN = [
  ['카드단말기', '결제 단말기'],
  ['포스기', 'POS 시스템'],
  ['매장', '점포', '영업장'],
  ['사장님', '점주님'],
];
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

/* ctx: {지역, 시도, 시군구, 동, 제품, 업종, 업소수, 업종1…} */
function fill(t, ctx) {
  let s = String(t).replace(/\{([^{}]{1,6})\}/g, (m, k) => (ctx[k] !== undefined && ctx[k] !== null ? String(ctx[k]) : m));
  const names = [ctx['지역'], ctx['시도'], ctx['시군구'], ctx['동'], ctx['제품'], ctx['업종'], ctx['업종1'], ctx['업종2'], ctx['업종3']].filter(Boolean);
  return fixJosa(s, names);
}
/* 본문 문단에만 동의어를 섞는다. 제목·H2 는 키워드를 지키려고 건드리지 않는다.
   첫 등장은 그대로 두고 이후 등장을 시드에 따라 번갈아 바꾼다. */
function syn(s, seed) {
  for (let g = 0; g < SYN.length; g++) {
    const grp = SYN[g];
    const mode = fnv(seed + '#' + g) % (grp.length + 1);
    if (mode === 0) continue;
    let n = 0;
    s = s.replace(new RegExp(grp[0], 'g'), m => { n++; if (n === 1) return m; return (n + mode) % 2 === 0 ? grp[mode % grp.length] || m : m; });
  }
  return fixJosa(s, ['결제 단말기', 'POS 시스템', '점포', '영업장', '점주님', '카드단말기', '포스기', '매장', '사장님']);
}
function para(t, ctx, seed) { return syn(fill(t, ctx), seed); }

