const PRICE_LINE = '설치비·가맹비·관리비 0원 · 유선 월 9,900원부터 · 매출 구간 확인 후 우대수수료 안내';

function favicon() {
  return 'data:image/svg+xml,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="${SITE.color}"/><text x="32" y="43" font-size="30" text-anchor="middle" fill="#fff" font-family="Arial" font-weight="700">${SITE.mark}</text></svg>`);
}

