function head(o) {
  const ld = (o.ld || []).map(x => `<script type="application/ld+json">${JSON.stringify(x)}</script>`).join('');
  return `<!DOCTYPE html><html lang="ko"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(o.title)}</title><meta name="description" content="${esc(o.desc)}">
<link rel="canonical" href="${ORIGIN}${o.path}">${o.noindex ? '<meta name="robots" content="noindex,follow">' : ''}
<meta property="og:type" content="website"><meta property="og:site_name" content="${esc(SITE.brand)}"><meta property="og:title" content="${esc(o.title)}"><meta property="og:description" content="${esc(o.desc)}"><meta property="og:url" content="${ORIGIN}${o.path}"><meta property="og:locale" content="ko_KR">
<meta name="theme-color" content="${SITE.color}"><link rel="icon" href="${favicon()}">
<style>${CSS}</style>${ld}</head><body>`;
}

function header(active) {
  const nav = ACTIVE.map(p => `<a href="/${p.key}/"${active === p.key ? ' class="on"' : ''}>${p.ko}</a>`).join('') + `<a href="/guide/"${active === 'guide' ? ' class="on"' : ''}>가이드</a>`;
  return `<header class="hd"><div class="w"><a class="logo" href="/">${esc(SITE.brand)}</a><nav class="nav">${nav}</nav></div></header>`;
}

function crumbs(items) {
  const vis = items.map((it, i) => (it.href && i < items.length - 1 ? `<a href="${it.href}">${esc(it.name)}</a>` : `<span>${esc(it.name)}</span>`) + (i < items.length - 1 ? '<span class="sep">›</span>' : '')).join('');
  const ld = { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: items.map((it, i) => ({ '@type': 'ListItem', position: i + 1, name: it.name, item: ORIGIN + it.href })) };
  return { html: `<div class="crumb">${vis}</div>`, ld };
}

function hero(o) {
  return `<section class="hero"><div class="w">${o.crumb || ''}<h1>${esc(o.h1)}</h1><p class="hook">${esc(o.hook)}</p><span class="price">${PRICE_LINE}</span>
<div class="btns"><button class="btn pri" type="button" data-open="1" data-tk="contact">무료 상담 신청</button><a class="btn sec" href="tel:${SITE.tel}">📞 ${SITE.telView}</a></div></div></section>`;
}

function footer() {
  const pl = ACTIVE.map(p => `<a href="/${p.key}/">${p.ko}</a>`).join('');
  return `<footer class="ft"><div class="w"><div class="links">${pl}<a href="/guide/">가이드</a><a href="/list">전체 목록</a></div>
<p style="margin-top:12px">${esc(SITE.brand)} · ${esc(SITE.tagline)}</p><p>문의 ${SITE.telView} · ${esc(SITE.email)}</p>
<p>상권 수치 출처: ${esc(REG.SRC)}. 설치 조건과 요금은 매장 환경·계약 조건에 따라 상담 시 안내합니다.</p></div></footer>`;
}

function floating() {
  const k = SITE.kakao ? `<a class="k" href="${SITE.kakao}" target="_blank" rel="noopener" data-tk="contact" aria-label="카카오톡 상담">카톡</a>` : '';
  return `<div class="fl">${k}<button class="q" type="button" data-open="1" aria-label="상담 문의">문의</button><a class="t" href="tel:${SITE.tel}" aria-label="전화 상담">전화</a></div>`;
}

function modal(prodKey) {
  const opts = ['<option value="">선택해 주세요</option>'].concat(PRODUCTS.map(p => `<option${p.key === prodKey ? ' selected' : ''}>${p.form}</option>`), ['<option>📦 패키지 (여러 장비)</option>']).join('');
  const biz = ['<option value="">선택</option>'].concat(BIZ.map(b => `<option>${b.ko}</option>`), ['<option>기타</option>']).join('');
  return `<div class="md" id="md" role="dialog" aria-modal="true" aria-label="상담 신청"><div class="mdb">
<div id="ct-form"><h3>무료 상담 신청 <button class="x" type="button" data-close="1" aria-label="닫기">×</button></h3>
<label for="ct-name">상호명</label><input id="ct-name" autocomplete="organization" placeholder="상호 또는 성함">
<label for="ct-phone">연락처</label><input id="ct-phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="010-0000-0000">
<label for="ct-addr">설치 주소</label><div class="row"><input id="ct-addr" readonly placeholder="주소 검색"><button class="btn solid" type="button" onclick="searchAddr()">검색</button></div>
<input id="ct-addr2" style="margin-top:6px" placeholder="상세 주소">
<label for="ct-biz">업종</label><select id="ct-biz">${biz}</select>
<label for="ct-product">상품 선택</label><select id="ct-product">${opts}</select>
<label for="ct-msg">문의 내용</label><textarea id="ct-msg" rows="3" placeholder="${esc(SITE.formHint)}"></textarea>
<div class="agree">수집 항목: 상호(이름), 연락처, 주소, 문의 내용 · 수집 목적: 상담 문의 접수 및 답변, 견적 안내 · 보유 기간: 문의 처리 완료 후 1년 이내 파기. 동의를 거부할 수 있으며, 거부 시 문의 접수가 제한됩니다. 문의 접수 시 위 내용에 동의한 것으로 간주합니다.</div>
<button class="btn solid ct-submit" type="button" style="width:100%;justify-content:center;margin-top:12px" onclick="submitForm()">상담 신청하기</button></div>
<div class="ok" id="ct-success"><div style="font-size:40px">✅</div><h3 style="justify-content:center">문의가 접수되었습니다</h3><p>확인 후 연락드리겠습니다.<br>급하시면 <a href="tel:${SITE.tel}"><b>${SITE.telView}</b></a>로 전화 주세요.</p><button class="btn solid" type="button" data-close="1" style="margin-top:12px">닫기</button></div>
</div></div>
<script src="https://t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js" defer></script>
<script>
(function(){var m=document.getElementById('md');document.addEventListener('click',function(e){var o=e.target.closest&&e.target.closest('[data-open]');if(o){m.classList.add('on');return;}var c=e.target.closest&&e.target.closest('[data-close]');if(c||e.target===m)m.classList.remove('on');});})();
function searchAddr(){
 new daum.Postcode({
 oncomplete:function(data){
 document.getElementById('ct-addr').value=data.roadAddress||data.jibunAddress;
 document.getElementById('ct-addr2').focus();
 }
 }).open();
}
function submitForm(){
 var name=document.getElementById('ct-name').value.trim();
 var phone=document.getElementById('ct-phone').value.trim();
 if(!name){alert('상호(이름)을 입력해주세요.');return;}
 if(!phone){alert('연락처를 입력해주세요.');return;}
 var addr=document.getElementById('ct-addr').value.trim();
 if(!addr){alert('주소를 검색해주세요.');return;}
 var addr2=document.getElementById('ct-addr2').value.trim();
 var product=document.getElementById('ct-product').value;
 if(!product){alert('문의 제품을 선택해주세요.');return;}
 var biz=document.getElementById('ct-biz').value;
 var msg=document.getElementById('ct-msg').value.trim();
 var btn=document.querySelector('.ct-submit');
 btn.textContent='접수 중...';btn.disabled=true;
 var p=new URLSearchParams();
 p.append('name',name);p.append('phone',phone);p.append('addr',addr+' '+addr2);
 p.append('product',product);p.append('biz',biz);p.append('msg',msg);
 var img=new Image();
 img.src='${GAS_URL}?'+p.toString();
 setTimeout(function(){
  document.getElementById('ct-form').style.display='none';
  document.getElementById('ct-success').classList.add('on');
  try{navigator.sendBeacon('/api/track',new Blob([JSON.stringify({type:'contact',page:location.pathname,ref:document.referrer,b:'상담 신청 접수'})],{type:'application/json'}));}catch(e){}
 },2000);
}
</script>`;
}

function page(o) {
  /* 설명문이 70자에 못 미치면 사이트 소개를 덧붙인다 */
  if (o.desc && o.desc.length < 70 && !o.noindex) o = { ...o, desc: clip(o.desc + ' ' + SITE.brand + '에서 ' + SITE.tagline + '를 지역·업종별로 확인하세요.', 70, 150) };
  const ld = (o.ld || []).concat([{ '@context': 'https://schema.org', '@type': 'Organization', name: SITE.brand, url: ORIGIN + '/', email: SITE.email, telephone: SITE.telView }]);
  return head({ ...o, ld }) + header(o.active) + (o.top || '') + `<main><div class="w">${o.body}</div></main>` + footer() + floating() + modal(o.prod) + TRACK_JS + '</body></html>';
}

function sec(h2, inner, cls) { return `<section class="sec${cls ? ' ' + cls : ''}"><h2>${esc(h2)}</h2>${inner}</section>`; }
function ps(arr, ctx, seed) { return arr.map((t, i) => `<p>${esc(para(t, ctx, seed + ':' + i))}</p>`).join(''); }
function links(arr) { return `<div class="links">${arr.map(l => `<a href="${l.href}">${esc(l.name)}</a>`).join('')}</div>`; }
function faqBlock(list, ctx, seed, h2) {
  const html = list.map((f, i) => `<details${i === 0 ? ' open' : ''}><summary>${esc(fill(f.q, ctx))}</summary><p>${esc(para(f.a, ctx, seed + ':f' + i))}</p></details>`).join('');
  const ld = { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: list.map((f, i) => ({ '@type': 'Question', name: fill(f.q, ctx), acceptedAnswer: { '@type': 'Answer', text: para(f.a, ctx, seed + ':f' + i) } })) };
  return { html: `<section class="sec faq"><h2>${esc(h2)}</h2>${html}</section>`, ld };
}

/* 각도 섹션 하나 렌더 */
function angleSection(s, ctx, seed) {
  const h2 = fill(pick1(s.h2, seed + ':h2:' + s.id), ctx);
  const pk = ctx._p;
  const lead = ps(pickN(forProd(s.lead, pk), seed + ':lead:' + s.id, 2), ctx, seed + ':l:' + s.id);
  let inner = lead;
  if (s.kind !== 'prose' && s.items && s.items.length) {
    const its = pickN(forProd(s.items, pk), seed + ':it:' + s.id, s.kind === 'table' ? 5 : 4);
    /* 번호 타임라인은 풀에 적힌 순서를 지킨다 */
    if (s.kind === 'steps') its.sort((x, y) => s.items.indexOf(x) - s.items.indexOf(y));
    if (s.kind === 'steps') inner += `<ol class="steps">${its.map((it, i) => `<li><h3>${esc(fill(it.t, ctx))}</h3><p>${esc(para(it.d, ctx, seed + ':s' + s.id + i))}</p></li>`).join('')}</ol>`;
    else if (s.kind === 'table') inner += `<table class="tbl"><tbody>${its.map((it, i) => `<tr><th>${esc(fill(it.t, ctx))}</th><td>${esc(para(it.d, ctx, seed + ':t' + s.id + i))}</td></tr>`).join('')}</tbody></table>`;
    else inner += `<div class="grid">${its.map((it, i) => `<div class="card"><h3>${esc(fill(it.t, ctx))}</h3><p>${esc(para(it.d, ctx, seed + ':c' + s.id + i))}</p></div>`).join('')}</div>`;
  }
  return sec(h2, inner);
}

function num(n) { return Number(n).toLocaleString('ko-KR'); }

/* 상권 데이터 섹션 (동) */
function marketSection(di, ctx, seed) {
  const d = REG.DONG[di];
  const total = d[3], top = d[4];
  /* 업소가 너무 적은 동은 비중 수치가 왜곡돼 섹션을 뺀다 */
  if (!total || total < 30 || !top.length) return '';
  const names = top.map(t => REG.MID[t[0]].trim());
  const mctx = { ...ctx, '업소수': num(total), '업종1': names[0], '업종1수': num(top[0][1]), '업종2': names[1] || names[0], '업종2수': num((top[1] || top[0])[1]), '업종3': names[2] || names[1] || names[0] };
  const max = top[0][1];
  const bars = top.map(t => `<div class="bar"><span>${esc(REG.MID[t[0]].trim())}</span><i style="width:${Math.max(4, Math.round(t[1] / max * 100))}%"></i><em>${num(t[1])}곳</em></div>`).join('');
  const share = Math.round(top[0][1] / total * 1000) / 10;
  const stats = `<div class="stats"><div class="stat"><b>${num(total)}</b><span>등록 상가 업소</span></div><div class="stat"><b>${esc(names[0])}</b><span>가장 많은 업종</span></div><div class="stat"><b>${share}%</b><span>${esc(names[0])} 비중</span></div></div>`;
  const text = ps(pickN(forProd(C.market, ctx._p), seed + ':mk', 2), mctx, seed + ':mk');
  return sec(`${ctx['동']} 상권 데이터 — 업종 분포`, stats + bars + text + `<p class="src">출처: ${esc(REG.SRC)} · 법정동 기준 · 상위 5개 중분류</p>`);
}

/* ---------- 페이지: 동 ---------- */
function dongPage(prod, sd, sg, dg) {
  const si = SIDO_BY[sd], gi = SG_BY[sd + '/' + sg], di = DONG_BY[sd + '/' + sg + '/' + dg];
  const S = REG.SIDO[si], G = REG.SG[gi], D = REG.DONG[di];
  const path = `/${prod.key}/${sd}/${sg}/${dg}/`;
  const seed = path;
  const ctx = { '시도': S[1], '시군구': G[2], '동': D[2], '지역': D[2], '제품': prod.ko, _p: prod.key };
  const h1 = fill(pick1(C.h1, seed + ':h1'), ctx);
  const hook = fill(pick1(C.hook, seed + ':hook'), ctx);
  const cr = crumbs([{ name: '홈', href: '/' }, { name: prod.ko, href: `/${prod.key}/` }, { name: S[2], href: `/${prod.key}/${sd}/` }, { name: G[2], href: `/${prod.key}/${sd}/${sg}/` }, { name: D[2], href: path }]);
  const tabs = ACTIVE.length < 2 ? '' : `<nav class="tabs" aria-label="${esc(D[2])} 제품"><div class="w">${ACTIVE.map(p => `<a href="/${p.key}/${sd}/${sg}/${dg}/"${p.key === prod.key ? ' class="on"' : ''}>${esc(D[2])} ${p.ko}</a>`).join('')}</div></nav>`;

  const blocks = {};
  blocks.intro = sec(fill(SITE.introH2, ctx), ps(pickN(forProd(C.intro, ctx._p), seed + ':intro', 2), ctx, seed + ':in') + ps(pickN(C.productNote[prod.key], seed + ':pn', 1), ctx, seed + ':pn'));
  C.sections.forEach((s, i) => { blocks['a' + i] = angleSection(s, ctx, seed); });
  blocks.market = marketSection(di, ctx, seed);
  const cs = pickN(forProd(C.cases, ctx._p), seed + ':case', 3);
  blocks.cases = sec(fill(SITE.casesH2, ctx), `<div class="grid">${cs.map((c, i) => `<div class="card"><h3>${esc(fill(c.t, ctx))}</h3><p>${esc(para(c.d, ctx, seed + ':cs' + i))}</p></div>`).join('')}</div>`);
  const set = pick1(C.process.sets, seed + ':pset');
  blocks.process = sec(fill(pick1(C.process.h2, seed + ':ph2'), ctx), `<ol class="steps">${set.map((st, i) => `<li><h3>${esc(fill(st.t, ctx))}</h3><p>${esc(para(st.d, ctx, seed + ':ps' + i))}</p></li>`).join('')}</ol>`);
  const fq = faqBlock(pickN(forProd(C.faq, ctx._p), seed + ':faq', 4), ctx, seed, `${D[2]} ${prod.ko} 자주 묻는 질문`);
  blocks.faq = fq.html;
  blocks.cta = sec(fill(pick1(C.cta.h2, seed + ':cta'), ctx), `<p>${esc(para(pick1(C.cta.p, seed + ':ctap'), ctx, seed + ':ctap'))}</p><div class="btns"><button class="btn pri" type="button" data-open="1" data-tk="contact">무료 상담 신청</button><a class="btn sec" href="tel:${SITE.tel}">📞 ${SITE.telView}</a></div>`, 'ctab');
  const sib = SG_DONGS[gi].filter(x => x !== di).map(x => ({ name: REG.DONG[x][2] + ' ' + prod.ko, href: `/${prod.key}/${sd}/${sg}/${REG.DONG[x][1]}/` }));
  blocks.siblings = sib.length ? sec(`${G[2]} 다른 동 ${prod.ko}`, links(sib) + `<p style="margin-top:10px"><a href="/${prod.key}/${sd}/${sg}/">${esc(G[2])} 전체 보기 →</a></p>`) : '';

  const body = SITE.dongOrder.map(k => blocks[k] || '').join('');
  const title = fill(SITE.titles.dong, ctx);
  const desc = clip(fill(SITE.descs.dong, ctx) + ' ' + hook, 70, 150);
  const svc = { '@context': 'https://schema.org', '@type': 'Service', name: `${D[2]} ${prod.ko}`, serviceType: prod.ko, provider: { '@type': 'Organization', name: SITE.brand }, areaServed: { '@type': 'AdministrativeArea', name: `${S[1]} ${G[2]} ${D[2]}` } };
  return page({ title, desc, path, prod: prod.key, active: prod.key, top: hero({ crumb: cr.html, h1, hook }) + tabs, body, ld: [cr.ld, svc, fq.ld] });
}

function clip(s, min, max) {
  s = s.replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const cut = s.slice(0, max);
  const k = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('다.'));
  return k >= min ? cut.slice(0, k + (cut[k] === '다' ? 2 : 1)).trim() : cut.slice(0, max - 1).trim() + '…';
}

/* ---------- 페이지: 시군구 ---------- */
function sigunguPage(prod, sd, sg) {
  const si = SIDO_BY[sd], gi = SG_BY[sd + '/' + sg];
  const S = REG.SIDO[si], G = REG.SG[gi];
  const path = `/${prod.key}/${sd}/${sg}/`, seed = path;
  const ctx = { '시도': S[1], '시군구': G[2], '지역': G[2], '제품': prod.ko, _p: prod.key };
  const cr = crumbs([{ name: '홈', href: '/' }, { name: prod.ko, href: `/${prod.key}/` }, { name: S[2], href: `/${prod.key}/${sd}/` }, { name: G[2], href: path }]);
  const dongs = SG_DONGS[gi];
  const total = dongs.reduce((a, x) => a + REG.DONG[x][3], 0);
  const ranked = dongs.filter(x => REG.DONG[x][3] > 0).sort((a, b) => REG.DONG[b][3] - REG.DONG[a][3]).slice(0, 6);
  const max = ranked.length ? REG.DONG[ranked[0]][3] : 1;
  const mk = total ? sec(`${G[2]} 동별 상가 업소 수`, `<div class="stats"><div class="stat"><b>${num(total)}</b><span>${esc(G[2])} 등록 상가 업소</span></div><div class="stat"><b>${dongs.length}</b><span>안내 중인 동</span></div></div><div class="bars">${ranked.map(x => `<div class="bar"><span>${esc(REG.DONG[x][2])}</span><i style="width:${Math.max(4, Math.round(REG.DONG[x][3] / max * 100))}%"></i><em>${num(REG.DONG[x][3])}곳</em></div>`).join('')}</div><p class="src">출처: ${esc(REG.SRC)}</p>`) : '';
  const s1 = C.sections[fnv(seed) % C.sections.length];
  const fq = faqBlock(pickN(forProd(C.faq, ctx._p), seed + ':faq', 3), ctx, seed, `${G[2]} ${prod.ko} 자주 묻는 질문`);
  const body = sec(`${G[2]} 동별 ${prod.ko} 안내`, links(dongs.map(x => ({ name: REG.DONG[x][2], href: `${path}${REG.DONG[x][1]}/` }))))
    + sec(fill(SITE.introH2, ctx), ps(pickN(forProd(C.intro, ctx._p), seed + ':intro', 2), ctx, seed))
    + mk + angleSection(s1, ctx, seed) + fq.html
    + sec(`${S[2]} 다른 지역`, links(SIDO_SGS[si].filter(x => x !== gi).map(x => ({ name: REG.SG[x][2], href: `/${prod.key}/${sd}/${REG.SG[x][1]}/` }))));
  return page({ title: fill(SITE.titles.sigungu, ctx), desc: clip(fill(SITE.descs.sigungu, ctx) + ' ' + fill(pick1(C.hook, seed), ctx), 70, 150), path, prod: prod.key, active: prod.key, top: hero({ crumb: cr.html, h1: fill(pick1(C.h1, seed + ':h1'), ctx), hook: fill(pick1(C.hook, seed + ':hook'), ctx) }), body, ld: [cr.ld, fq.ld] });
}

